CREATE TABLE `info` (
  `INFO_ID` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `INFO_DATE` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `INFO_DESP` text,
  `INFO_STATUS` varchar(45) NOT NULL DEFAULT '',
  `CREATED_BY` varchar(45) NOT NULL DEFAULT '',
  `UPDATED_BY` varchar(45) NOT NULL DEFAULT '',
  `CREATED_ON` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `INFO_REMARK` varchar(45) NOT NULL DEFAULT '',
  PRIMARY KEY (`INFO_ID`)
) ENGINE=MyISAM AUTO_INCREMENT=61 DEFAULT CHARSET=utf8;
