CREATE TABLE `mobileusers` (
  `userID` varchar(50) NOT NULL DEFAULT '',
  `userPwd` varchar(32) NOT NULL DEFAULT '',
  `userGrpID` varchar(12) NOT NULL DEFAULT '',
  `userName` varchar(50) NOT NULL DEFAULT '',
  `userBranch` varchar(50) NOT NULL DEFAULT '',
  `userDept` varchar(50) NOT NULL DEFAULT '',
  `userCty` varchar(35) NOT NULL DEFAULT '',
  `userEmail` varchar(3000) NOT NULL DEFAULT '',
  `lastLogin` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `userDirectory` varchar(15) NOT NULL DEFAULT 'default',
  `linktoams` char(1) NOT NULL DEFAULT '',
