  `start_time` time NOT NULL DEFAULT '00:00:00',
  `end_time` time NOT NULL DEFAULT '00:00:00',
  `userphone` varchar(45) DEFAULT NULL,
  `comsta` char(1) DEFAULT 'Y',
  `itemgroup` varchar(200) NOT NULL DEFAULT '',
  `project` varchar(200) NOT NULL DEFAULT '',
  `created_by` varchar(200) DEFAULT '',
  `job` varchar(200) NOT NULL DEFAULT '',
  `agent` varchar(200) DEFAULT '',
  PRIMARY KEY (`userID`),
  KEY `USERINFO` (`userID`,`userPwd`,`userGrpID`,`userName`,`userBranch`,`userDept`,`userCty`,`lastLogin`,`userDirectory`,`linktoams`) USING BTREE
) ENGINE=MyISAM DEFAULT CHARSET=utf8;
